class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for v in arr:
        node = ListNode(v)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def next_larger_nodes(head_arr):
    head = arr_to_list(head_arr)
    values = []
    node = head
    while node:
        values.append(node.val)
        node = node.next

    result = [0] * len(values)
    stack = []
    for i, val in enumerate(values):
        while stack and values[stack[-1]] < val:
            result[stack.pop()] = val
        stack.append(i)

    return result

